def rle(s):
    if not s:
        return ''
    result = []
    count = 1
    for char in s[1:]:
        if char == s[0]:
            count += 1
        else:
            result.append(f"{s[0]}{count}")
            count = 1
    result.append(f"{s[0]}{count}")
    return ''.join(result)

def balanced(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()
    return not stack

def to_base(n, b):
    if n == 0:
        return "0"
    digits = "0123456789abcdef"
    result = ""
    while n > 0:
        result = digits[n % b] + result
        n //= b
    return result
